function isRotation(s: string, goal: string): boolean {
  if (s.length !== goal.length) return false;
  const n = goal.length, fail = new Array(n).fill(0);
  for (let i = 1, j = 0; i < n; i++) {
    while (j > 0 && goal[i] !== goal[j]) j = fail[j - 1];
    if (goal[i] === goal[j]) j++;
    fail[i] = j;
  }
  const text = s + s;
  for (let i = 0, j = 0; i < text.length; i++) {
    while (j > 0 && text[i] !== goal[j]) j = fail[j - 1];
    if (text[i] === goal[j]) j++;
    if (j === n) return true;
  }
  return false;
}

